/// <summary>
///     The <c>AVACleanUpTmpTables</c> class is the execution class for deleting tmp tables
/// </summary>
final class AVACleanUpTmpTables
{
}

Method.Source:
/// <summary>
///     AVA <c>main</c> method.
/// </summary>
/// <param name="_args">
///     <c>Args</c> as type
/// </param>
public static void main(Args _args)
{
    AVACleanUpTmpTables locJobClass;

    locJobClass = new AVACleanUpTmpTables();

    locJobClass.cleanUpSalesQuotationTmp();
    locJobClass.cleanUpAVASalesOrderDelegationReportTmp();
    locJobClass.cleanUpAVASalesQuotationRequestStatsReportTmp();
    locJobClass.cleanUpAVAsmmActivitiesWeeklyPlanADMReportTmp();
}

/// <summary>
///     AVA <c>cleanUpSalesQuotationTmp</c> method.
/// </summary>
public void cleanUpSalesQuotationTmp()
{
    SalesQuotationDetailsTmp    locSalesQuotationDetailsTmp;
    SalesQuotationHeaderTmp     locSalesQuotationHeaderTmp;

    delete_from locSalesQuotationDetailsTmp;
    delete_from locSalesQuotationHeaderTmp;
}

