{
    AVASalesOrderDelegationReportNoteTmp    locAVASalesOrderDelegationReportNoteTmp;
    AVASalesOrderDelegationReportMarkupTmp  locAVASalesOrderDelegationReportMarkupTmp;
    AVASalesOrderDelegationReportDetailTmp  locAVASalesOrderDelegationReportDetailTmp;
    AVASalesOrderDelegationReportHeaderTmp  locAVASalesOrderDelegationReportHeaderTmp;

    delete_from locAVASalesOrderDelegationReportNoteTmp;
    delete_from locAVASalesOrderDelegationReportMarkupTmp;
    delete_from locAVASalesOrderDelegationReportDetailTmp;
    delete_from locAVASalesOrderDelegationReportHeaderTmp;
}

