    delete_from locAVASalesQuotRequestStatsReportHeaderTmp;
}

/// <summary>
///     AVA <c>cleanUpAVAsmmActivitiesWeeklyPlanADMReportTmp</c> method.
/// </summary>
public void cleanUpAVAsmmActivitiesWeeklyPlanADMReportTmp()
{
    AVAActivitiesWeeklyPlanReportDetailTmp  locDetailTmp;
